use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH, Duration};

use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

/// HMAC-based token authentication service
/// Tokens have format: base64(payload).base64(signature)
/// Signature = HMAC-SHA256(secret, payload)

const SECRET_KEY: &[u8] = b"super_secret_key_for_hmac_signing_2024";
const TOKEN_VERSION: u8 = 2;

#[derive(Clone, Debug)]
pub struct TokenPayload {
    pub user_id: u64,
    pub role: String,
    pub issued_at: u64,
    pub expires_at: u64,
    pub version: u8,
}

#[derive(Clone)]
pub struct SessionStore {
    sessions: Arc<Mutex<HashMap<u64, TokenPayload>>>,
}

impl SessionStore {
    pub fn new() -> Self {
        SessionStore {
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn store_session(&self, payload: &TokenPayload) {
        let mut sessions = self.sessions.lock().unwrap();
        sessions.insert(payload.user_id, payload.clone());
    }

    pub fn get_session(&self, user_id: u64) -> Option<TokenPayload> {
        let sessions = self.sessions.lock().unwrap();
        sessions.get(&user_id).cloned()
    }

    pub fn revoke_session(&self, user_id: u64) {
        let mut sessions = self.sessions.lock().unwrap();
        sessions.remove(&user_id);
    }
}

/// Compute HMAC-SHA256 using a real, vetted cryptographic implementation.
fn hmac_sha256(key: &[u8], message: &[u8]) -> [u8; 32] {
    let mut mac = HmacSha256::new_from_slice(key)
        .expect("HMAC can take a key of any size");
    mac.update(message);
    let result = mac.finalize().into_bytes();
    let mut out = [0u8; 32];
    out.copy_from_slice(&result);
    out
}

/// Encode payload to bytes
fn encode_payload(payload: &TokenPayload) -> Vec<u8> {
    let mut data = Vec::new();
    data.push(payload.version);
    data.extend_from_slice(&payload.user_id.to_le_bytes());
    data.extend_from_slice(&payload.issued_at.to_le_bytes());
    data.extend_from_slice(&payload.expires_at.to_le_bytes());
    let role_bytes = payload.role.as_bytes();
    data.push(role_bytes.len() as u8);
    data.extend_from_slice(role_bytes);
    data
}

/// Decode payload from bytes
fn decode_payload(data: &[u8]) -> Option<TokenPayload> {
    if data.len() < 26 {
        return None;
    }
    let version = data[0];
    if version != TOKEN_VERSION {
        return None;
    }
    let user_id = u64::from_le_bytes(data[1..9].try_into().ok()?);
    let issued_at = u64::from_le_bytes(data[9..17].try_into().ok()?);
    let expires_at = u64::from_le_bytes(data[17..25].try_into().ok()?);
    let role_len = data[25] as usize;
    if data.len() < 26 + role_len {
        return None;
    }
    let role = String::from_utf8(data[26..26+role_len].to_vec()).ok()?;
    Some(TokenPayload { user_id, role, issued_at, expires_at, version })
}

/// Simple base64 encode
fn b64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let triple = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((triple >> 18) & 0x3F) as usize] as char);
        result.push(CHARS[((triple >> 12) & 0x3F) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((triple >> 6) & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(triple & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

/// Simple base64 decode
fn b64_decode(s: &str) -> Option<Vec<u8>> {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = Vec::new();
    let bytes: Vec<u8> = s.bytes().filter(|&b| b != b'\n' && b != b'\r').collect();
    for chunk in bytes.chunks(4) {
        if chunk.len() < 4 { break; }
        let vals: Vec<u32> = chunk.iter().map(|&c| {
            if c == b'=' { 0 } else { CHARS.iter().position(|&x| x == c).unwrap_or(0) as u32 }
        }).collect();
        let triple = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3];
        result.push(((triple >> 16) & 0xFF) as u8);
        if chunk[2] != b'=' { result.push(((triple >> 8) & 0xFF) as u8); }
        if chunk[3] != b'=' { result.push((triple & 0xFF) as u8); }
    }
    Some(result)
}

/// Determine the effective comparison length for signature verification.
/// All versions require full 32-byte signature comparison.
fn effective_sig_length(_claimed_sig: &[u8], _version: u8) -> usize {
    // Always compare full 32-byte HMAC-SHA256 signature
    32
}

/// Constant-time comparison of two byte slices up to `len` bytes
fn secure_compare(a: &[u8], b: &[u8], len: usize) -> bool {
    if len == 0 {
        return false; // Zero-length comparison is always rejected
    }
    if a.len() < len || b.len() < len {
        return false;
    }
    let mut result = 0u8;
    for i in 0..len {
        result |= a[i] ^ b[i];
    }
    result == 0
}

/// Generate a signed token for the given payload
pub fn generate_token(payload: &TokenPayload) -> String {
    let payload_bytes = encode_payload(payload);
    let signature = hmac_sha256(SECRET_KEY, &payload_bytes);
    format!("{}.{}", b64_encode(&payload_bytes), b64_encode(&signature))
}

/// Verify and decode a token, returning the payload if valid
pub fn verify_token(token: &str) -> Option<TokenPayload> {
    let parts: Vec<&str> = token.splitn(2, '.').collect();
    if parts.len() != 2 {
        return None;
    }

    let payload_bytes = b64_decode(parts[0])?;
    let claimed_sig = b64_decode(parts[1])?;

    // Decode payload first to get version for sig length policy
    let payload = decode_payload(&payload_bytes)?;

    // Compute expected signature
    let expected_sig = hmac_sha256(SECRET_KEY, &payload_bytes);

    // Determine comparison length - always full 32 bytes
    let cmp_len = effective_sig_length(&claimed_sig, payload.version);

    // Verify signature with constant-time comparison
    if !secure_compare(&expected_sig, &claimed_sig, cmp_len) {
        return None;
    }

    // Check expiration
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::from_secs(0))
        .as_secs();

    if now > payload.expires_at {
        return None;
    }

    Some(payload)
}

/// Authentication middleware
pub struct AuthService {
    store: SessionStore,
}

impl AuthService {
    pub fn new() -> Self {
        AuthService {
            store: SessionStore::new(),
        }
    }

    pub fn login(&self, user_id: u64, role: &str) -> String {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or(Duration::from_secs(0))
            .as_secs();

        let payload = TokenPayload {
            user_id,
            role: role.to_string(),
            issued_at: now,
            expires_at: now + 3600, // 1 hour
            version: TOKEN_VERSION,
        };

        self.store.store_session(&payload);
        generate_token(&payload)
    }

    pub fn authenticate(&self, token: &str) -> Result<TokenPayload, &'static str> {
        let payload = verify_token(token).ok_or("Invalid or expired token")?;

        // Verify session still exists (not revoked)
        self.store.get_session(payload.user_id)
            .ok_or("Session revoked")?;

        Ok(payload)
    }

    pub fn logout(&self, user_id: u64) {
        self.store.revoke_session(user_id);
    }

    pub fn is_admin(&self, token: &str) -> bool {
        match self.authenticate(token) {
            Ok(payload) => payload.role == "admin",
            Err(_) => false,
        }
    }
}

fn main() {
    let service = AuthService::new();

    // Normal flow
    let token = service.login(1001, "user");
    println!("Generated token: {}", token);

    match service.authenticate(&token) {
        Ok(payload) => println!("Authenticated user {} with role {}", payload.user_id, payload.role),
        Err(e) => println!("Auth failed: {}", e),
    }

    // Admin check
    let admin_token = service.login(1, "admin");
    println!("Is admin: {}", service.is_admin(&admin_token));

    // Logout
    service.logout(1001);
    match service.authenticate(&token) {
        Ok(_) => println!("Should not reach here"),
        Err(e) => println!("After logout: {}", e),
    }
}
